// A quote of the day, set in a serif on a warm gradient.
export function get(app) {
  return (
    <div className="flex flex-col items-center justify-center gap-6 px-16 bg-gradient-to-br from-amber-100 via-orange-100 to-rose-200 text-stone-800">
      <span className="text-8xl text-rose-400 font-[Cormorant_Garamond] leading-none h-12">“</span>
      <span className="text-5xl text-center italic font-[Cormorant_Garamond] leading-tight line-clamp-4">
        The best way to predict the future is to invent it, one small frame at a time.
      </span>
      <div className="w-16 border-t-2 border-rose-300" />
      <span className="text-lg uppercase text-stone-500 font-[FiraGO]">Alan Kay, more or less</span>
    </div>
  )
}
